import {ratio,sum,predict,metrics,topicStats,wilson,experiments,forecast,parseCSV,csvText,validateBundle} from './analytics.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>n==null?'—':new Intl.NumberFormat('en-US').format(Math.round(n));
const compact=n=>n==null?'—':new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n);
const percent=n=>n==null?'—':(n*100).toFixed(1)+'%';
const decimal=n=>n==null?'—':n.toFixed(2);
const date=s=>new Date(s+'T00:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',content:'M4 4h16v16H4z M9 8l7 4-7 4z',audience:'M4 20v-2a5 5 0 0 1 10 0v2 M9 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 5a4 4 0 0 1 0 7 M17 15a5 5 0 0 1 4 5',experiments:'M9 3h6 M10 3v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3 M7 15h10',strategy:'M3 17l6-6 4 3 8-10 M15 4h6v6',data:'M3 5c0-4 18-4 18 0s-18 4-18 0 M3 5v14c0 4 18 4 18 0V5 M3 12c0 4 18 4 18 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',arrow:'M5 12h14 M13 6l6 6-6 6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',views:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',heart:'M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13',plus:'M12 4v16 M4 12h16',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17v.1 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',check:'M5 12l4 4L19 6'};
const icon=(name)=>`<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[name]||icons.file}"/></svg>`;
const nav=[['overview','Overview'],['content','Content library'],['audience','Audience sentiment'],['experiments','Experiments'],['strategy','Strategy & trends'],['data','Data studio']];
const state={tab:'overview',platform:'All platforms',topic:'All topics',start:'',end:'',chart:'views',search:'',page:1,sort:'viral',label:'All comments',contentMode:'performance',commentPage:1};
let demo,data,model,evaluation,series;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function current(){const posts=data.posts.filter(p=>(state.platform==='All platforms'||p.platform===state.platform)&&(state.topic==='All topics'||p.topic===state.topic)&&(!state.start||p.published_at>=state.start)&&(!state.end||p.published_at<=state.end));const ids=new Set(posts.map(p=>p.post_id));return {posts,comments:data.comments.filter(c=>ids.has(c.post_id))}}
const options=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const select=(id,values,value,label)=>`<div class="select-wrap"><label class="sr-only" for="${id}">${label}</label><select id="${id}">${options(values,value)}</select></div>`;
function render(){
 const tab=nav.find(n=>n[0]===state.tab)[1];const demoMode=data.meta.source==='synthetic_demo';
 $('#app').innerHTML=`<aside class="sidebar"><a href="#overview" class="brand" aria-label="Relate home"><div class="brandmark">${icon('overview')}</div><div class="brand-name">relate<span style="color:#83a65b">.</span></div><span>®</span></a><div class="workspace"><div class="workspace-icon">✳</div><div><div style="font-size:11px;font-weight:600">Seen & Understood</div><div class="small muted" style="font-size:9px">Content intelligence workspace</div></div></div><div class="eyebrow navlabel">Workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,label])=>`<button data-nav="${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} title="${label}">${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebottom"><div class="study"><div class="eyebrow" style="font-size:9px">The connection project</div><p>Small stories.<br>Measurable connection.</p><a href="reports/strategy-report.pdf" target="_blank" rel="noopener">Read the demo report ↗</a></div><div class="profile"><div class="avatar">SU</div><div><strong style="font-size:11px">Project workspace</strong><div style="font-size:9px" class="muted">Data Science · Major Project</div></div></div></div></aside>
 <div class="shell"><header class="topbar"><div class="crumb">Workspace <span>/</span> <strong>${tab}</strong></div><div class="topright"><span class="status"><i class="dot"></i>${demoMode?'Demo campaign':'Imported campaign'}</span><button class="round-icon" id="help" aria-label="Metric definitions">${icon('help')}</button></div></header><main class="main" id="main"><div class="pagehead"><div><h1>${{overview:'Understand what connects.',content:'Stories with something to say.',audience:'Listen beyond the likes.',experiments:'Let the evidence lead.',strategy:'Your next meaningful move.',data:'Good insights start here.'}[state.tab]}</h1><p>${{overview:'A clearer picture of your content, your audience, and what resonates.',content:'Explore performance and the creative ideas behind every post.',audience:'Find the moments your audience feels seen and understood.',experiments:'Compare opening hooks across matched content pairs.',strategy:'Turn audience signals into a thoughtful content plan.',data:'Bring in your campaign. Keep the analysis transparent.'}[state.tab]}</p></div><div class="actions"><button class="btn" id="export">${icon('download')} Export data</button><button class="btn primary" data-nav="${state.tab==='data'?'overview':'data'}">${icon(state.tab==='data'?'overview':'plus')}${state.tab==='data'?'Open overview':'Import campaign'}</button></div></div>
 ${state.tab!=='data'?`<div class="filters">${select('platform',['All platforms',...new Set(data.posts.map(p=>p.platform))],state.platform,'Filter by platform')}${select('topic',['All topics',...new Set(data.posts.map(p=>p.topic))],state.topic,'Filter by topic')}<div class="datebox"><label class="sr-only" for="start">Published from</label><input type="date" id="start" value="${state.start}" aria-label="Published from"><span class="muted">–</span><label class="sr-only" for="end">Published through</label><input type="date" id="end" value="${state.end}" aria-label="Published through"></div><button class="text-btn" id="reset-filters">Reset</button><span class="filter-end">${current().posts.length} posts <span style="padding:0 5px">·</span><span class="badge demo">${demoMode?'Synthetic demo data':'User-supplied data'}</span></span></div>`:''}
 <div id="view"></div><footer class="footer"><span>Relate · The Data-Driven Social Engagement Initiative</span><span>${demoMode?'All campaign results are simulated.':'Data stays in this browser session; export to retain it.'} · Local analysis, no tracking</span></footer></main></div>`;
 $('#view').innerHTML=({overview,content,audience,experiments:experimentView,strategy,data:dataView}[state.tab])();bind();
}
function lineChart(posts,key='views'){
 const by=new Map();for(const p of posts)by.set(p.published_at,(by.get(p.published_at)||0)+p[key]);const points=[...by].sort((a,b)=>a[0].localeCompare(b[0]));if(!points.length)return '<div class="empty">No posts in this date range.</div>';
 if(key==='followers_gained'){let total=0;points.forEach(p=>p[1]=total+=p[1])}
 const W=600,H=216,L=42,T=14,B=184,max=Math.max(...points.map(p=>p[1]),1)*1.15;
 const first=Date.parse(points[0][0]),last=Date.parse(points.at(-1)[0]);
 const xy=points.map(([d,v])=>[L+(Date.parse(d)-first)/Math.max(86400000,last-first)*(W-L-13),B-v/max*(B-T),d,v]);
 const path=xy.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
 const grid=Array.from({length:5},(_,i)=>{const y=B-i*(B-T)/4;return `<line x1="${L}" x2="${W}" y1="${y}" y2="${y}" class="gridline"/><text x="${L-10}" y="${y+4}" text-anchor="end">${compact(max*i/4)}</text>`}).join('');
 const ticks=xy.filter((_,i)=>i===0||i===xy.length-1||i%Math.max(1,Math.floor(xy.length/5))===0);
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${key==='views'?'Views by publication date':'Cumulative attributed follows by publication date'}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b8d698" stop-opacity=".35"/><stop offset="1" stop-color="#dfead4" stop-opacity=".03"/></linearGradient></defs>${grid}<path d="${path} L${xy.at(-1)[0]},${B} L${L},${B} Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#729255" stroke-width="2.3"/>${xy.map(([x,y,d,v])=>`<circle class="chart-point" cx="${x}" cy="${y}" r="3.2" fill="#729255" stroke="white" stroke-width="1.5"><title>${date(d)}: ${number(v)} ${key==='views'?'views':'attributed follows'}</title></circle>`).join('')}${ticks.map(([x,,d])=>`<text x="${x}" y="209" text-anchor="${x===L?'start':x===xy.at(-1)[0]?'end':'middle'}">${date(d)}</text>`).join('')}</svg>`;
}
function tinySpark(values){if(values.length<2)return '';const min=Math.min(...values),max=Math.max(...values);return `<svg class="spark" viewBox="0 0 80 30" aria-hidden="true"><path d="${values.map((v,i)=>`${i?'L':'M'}${i/(values.length-1)*80} ${27-(v-min)/Math.max(1,max-min)*23}`).join(' ')}" fill="none" stroke="#9bb97c" stroke-width="1.5"/></svg>`}
function metric(title,value,note,ico,values=[]){return `<div class="metric"><div class="metric-top">${title}${icon(ico)}</div><strong>${value}</strong><div class="metric-bottom">${note}</div>${tinySpark(values)}</div>`}
function kpis(posts,comments){const m=metrics(posts,comments);return `<div class="metrics">${metric('Total views',compact(m.views),`${number(posts.length)} published post records`,'views',posts.map(p=>p.views))}${metric('Engagement rate',percent(m.engagement),'All actions ÷ aggregate reach','heart')}${metric('Attributed follows',number(m.followers_gained),'Sum of post-level gains','audience',posts.map(p=>p.followers_gained))}${metric('Audience relatability',percent(m.relatableRate),`${number(m.analyzed)} comments analyzed`,'spark')}</div>`}
function donut(m){const p=(m.relatableRate||0)*100;return `<div class="connection"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="${percent(m.relatableRate)} classified Relatable"><circle cx="60" cy="60" r="48" fill="none" stroke="#e9ecdf" stroke-width="13"/><circle cx="60" cy="60" r="48" fill="none" stroke="#9eb874" stroke-width="13" stroke-dasharray="${p*3.016} 301.6" transform="rotate(-90 60 60)" stroke-linecap="round"/></svg><div class="center"><strong>${percent(m.relatableRate)}</strong><small>classified Relatable</small></div></div><div class="donut-legend"><div><span class="legend"><i style="background:#9eb874"></i>Relatable</span><strong>${number(m.relatable)}</strong></div><div><span class="legend"><i style="background:#e5e8d9"></i>Neutral</span><strong>${number(m.analyzed-m.relatable)}</strong></div></div></div>`}
function bars(topics){return topics.map((t,i)=>`<div class="barrow"><span>${esc(t.topic)}</span><div class="bartrack"><div class="barfill" style="width:${(t.relatableRate||0)*100}%;background:${['#52794a','#8eac70','#a9bd8c','#bdcda6','#d0dabc','#dde4d0'][i%6]}"></div></div><small>${percent(t.relatableRate)}</small></div>`).join('')}
function overview(){const {posts,comments}=current(),m=metrics(posts,comments),topics=topicStats(posts,comments),top=topics[0];return `${kpis(posts,comments)}<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Growth over time</h2><p>Grouped by publication date · fixed observation windows</p></div><div class="segmented"><button data-chart="views" class="${state.chart==='views'?'selected':''}">Views</button><button data-chart="followers_gained" class="${state.chart==='followers_gained'?'selected':''}">Follows</button></div></div>${lineChart(posts,state.chart)}<div class="note">${state.chart==='views'?'Views include repeat plays.':'Cumulative post-attributed gains; not net account follower growth.'} Hover over a point for exact values.</div></section><section class="panel"><div class="panel-head"><div><h2>A little more understood</h2><p>Comment classification, beyond positive or negative</p></div>${icon('heart')}</div>${donut(m)}<div class="insight">${icon('spark')}<span>${m.analyzed?`<strong>${number(m.relatable)} comments classified Relatable.</strong> Analyzed sample: ${percent(m.coverage)} of reported comments. Model labels need human review.`:'Import comments to measure audience connection.'}</span></div></section></div>
 <div class="grid2"><section class="panel"><div class="panel-head"><div><h2>What resonates most</h2><p>Relatable comments as a share of analyzed comments</p></div><button class="text-btn" data-nav="strategy">Explore insights ↗</button></div>${topics.length?bars(topics):'<div class="empty">No topics in this selection.</div>'}<div class="note">${top?`${esc(top.topic)} leads this selection · ${top.analyzed} comments across ${top.posts} posts.`:'Change filters to see topic performance.'}</div></section><section class="panel"><div class="panel-head"><div><h2>Signals that travel</h2><p>High-value actions and shareability</p></div>${icon('strategy')}</div><div class="stats-list"><div><span>Weighted viral score</span><strong>${decimal(m.viral)}</strong></div><div><span>Save-to-share ratio</span><strong>${decimal(m.saveShare)}${m.saveShare===null?'':'×'}</strong></div><div><span>Shares per reach</span><strong>${percent(m.shareRate)}</strong></div><div><span>View-weighted retention</span><strong>${percent(m.retention)}</strong></div></div><div class="insight" style="margin-top:18px">${icon('spark')}<span>The score weights shares ×3, saves ×2 and likes ×1 per 100 reach. It is a descriptive proxy, not a viral probability.</span></div></section></div>
 <section class="panel tabspacer"><div class="panel-head"><div><h2>Content making a connection</h2><p>Top posts by weighted viral score</p></div><button class="text-btn" data-nav="content">View all content ↗</button></div>${postTable([...posts].sort((a,b)=>postMetric(b,'viral')-postMetric(a,'viral')).slice(0,5),comments)}</section>`}
function postMetric(p,key){return metrics([p],data.comments.filter(c=>c.post_id===p.post_id))[key]??-1}
function postTable(posts,comments){return posts.length?`<div class="table-wrap"><table><thead><tr><th>Content</th><th>Platform</th><th>Views</th><th>Engagement</th><th>Relatability</th><th>Viral score</th><th></th></tr></thead><tbody>${posts.map(p=>{const m=metrics([p],comments.filter(c=>c.post_id===p.post_id)),asset=series.find(s=>s.id===p.content_id);return `<tr><td><div class="postcell">${asset?`<img class="thumb" src="${asset.asset}" alt="" loading="lazy">`:'<div class="thumb"></div>'}<div><div class="post-title">${esc(p.title)}</div><small>${esc(p.topic)} · ${date(p.published_at)} · ${esc(p.variant||'No variant')}</small></div></div></td><td>${esc(p.platform)}</td><td>${compact(p.views)}</td><td>${percent(m.engagement)}</td><td><span class="badge ${m.relatableRate<.5?'neutral':''}">${percent(m.relatableRate)}</span></td><td>${decimal(m.viral)}</td><td><button class="text-btn" data-post="${esc(p.post_id)}" aria-label="Inspect ${esc(p.title)}">View ↗</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No matching posts. Try a different topic or date range.</div>'}
function content(){const {posts,comments}=current();let filtered=posts.filter(p=>(p.title+' '+p.topic+' '+p.post_id).toLowerCase().includes(state.search.toLowerCase()));filtered.sort((a,b)=>state.sort==='date'?b.published_at.localeCompare(a.published_at):postMetric(b,state.sort)-postMetric(a,state.sort));const maxPage=Math.max(1,Math.ceil(filtered.length/8));state.page=Math.min(state.page,maxPage);
 const relevant=series.filter(s=>(state.topic==='All topics'||s.topic===state.topic)&&(!state.search||(s.title+' '+s.topic).toLowerCase().includes(state.search.toLowerCase())));
 return `<div class="tablebar"><div class="segmented"><button data-mode="performance" class="${state.contentMode==='performance'?'selected':''}">Performance</button><button data-mode="series" class="${state.contentMode==='series'?'selected':''}">The content series · 12</button></div><input class="search" id="content-search" placeholder="Search titles, topics or IDs…" aria-label="Search content" value="${esc(state.search)}"></div>${state.contentMode==='series'?`<div class="callout"><div><h2>Seen & Understood</h2><p>Twelve original concepts about the small things we share. Each includes an editable SVG card, a 25-second video script, a caption and two test hooks. Publication and performance are simulated. This creative library is fixed; platform and date filters apply to performance only.</p></div><a class="btn" href="reports/content-series.pdf" target="_blank" rel="noopener">${icon('download')} Content playbook</a></div><div class="cards">${relevant.map(s=>`<article class="content-card"><img src="${s.asset}" alt="${esc(s.hook_a)}" loading="lazy"><div class="content-info"><span class="topic-tag">${esc(s.topic)}</span><h3>${esc(s.title)}</h3><p>${s.id} · 25-second concept · 2 hook variants</p><div class="actions"><button class="text-btn" data-content="${s.id}">Script & caption ↗</button><a class="text-btn" href="content/png/${s.id}.png" download>Download PNG</a></div></div></article>`).join('')}</div>`:`${kpis(posts,comments)}<section class="panel tabspacer"><div class="panel-head"><div><h2>Every post, in perspective</h2><p>Inspect a post for its full metrics and comments.</p></div><div class="select-wrap"><label class="sr-only" for="sort">Sort posts</label><select id="sort"><option value="viral" ${state.sort==='viral'?'selected':''}>Viral score ↓</option><option value="views" ${state.sort==='views'?'selected':''}>Views ↓</option><option value="relatableRate" ${state.sort==='relatableRate'?'selected':''}>Relatability ↓</option><option value="date" ${state.sort==='date'?'selected':''}>Newest first</option></select></div></div>${postTable(filtered.slice((state.page-1)*8,state.page*8),comments)}<div class="panel-bottom"><span>${filtered.length} posts · Page ${state.page} of ${maxPage}</span><div class="actions"><button class="btn" id="prev" ${state.page===1?'disabled':''}>Previous</button><button class="btn" id="next" ${state.page===maxPage?'disabled':''}>Next</button></div></div></section>`}`}
function audience(){const {posts,comments}=current(),m=metrics(posts,comments),ci=wilson(m.relatable,m.analyzed);const filtered=comments.filter(c=>(state.label==='All comments'||(state.label==='Needs review'?c.review:c.label===state.label)));const pages=Math.max(1,Math.ceil(filtered.length/6));state.commentPage=Math.min(state.commentPage,pages);
 return `<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>The connection signal</h2><p>${number(m.analyzed)} analyzed comments from the current selection</p></div><span class="badge">English NLP</span></div>${donut(m)}<div class="insight">${icon('help')}<span>95% Wilson interval: ${ci?ci.map(percent).join(' – '):'not available'}. Describes sampling uncertainty in model labels; excludes model error and correlations between comments.</span></div></section><section class="panel"><div class="panel-head"><div><h2>Try a comment</h2><p>The same trained model runs locally in your browser.</p></div>${icon('spark')}</div><label class="form-label" for="comment-input">What did your audience say?</label><textarea id="comment-input" maxlength="3000" placeholder="I thought I was the only one who felt this way…"></textarea><button class="btn primary" id="analyze" style="margin-top:12px">Analyze comment ${icon('arrow')}</button><div id="prediction" aria-live="polite"></div></section></div>
 <div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Audience voices</h2><p>Labels are model outputs, not verified emotional states.</p></div>${select('comment-label',['All comments','Relatable','Neutral','Needs review'],state.label,'Filter comments')}</div><div class="comments">${filtered.slice((state.commentPage-1)*6,state.commentPage*6).map(c=>`<article class="comment"><div class="comment-meta"><div class="avatar" style="width:25px;height:25px;font-size:9px">${esc(c.comment_id.slice(-2))}</div><span>${esc(c.post_id)} · ${date(c.created_at)}</span><span class="badge ${c.label==='Neutral'?'neutral':''}">${c.label}</span></div><p>“${esc(c.text)}”</p><div class="comment-detail">Relatable model score: ${percent(c.score)}${c.review?' · Human review suggested':''}</div></article>`).join('')||'<div class="empty">No comments match this selection.</div>'}</div><div class="panel-bottom"><span>${number(filtered.length)} comments · ${state.commentPage}/${pages}</span><div class="actions"><button class="btn" id="comment-prev" ${state.commentPage===1?'disabled':''}>Previous</button><button class="btn" id="comment-next" ${state.commentPage===pages?'disabled':''}>Next</button></div></div></section><section class="panel"><div class="panel-head"><div><h2>Meet the model</h2><p>A transparent baseline you can inspect and retrain.</p></div></div><div class="stats-list"><div><span>Algorithm</span><strong>Naive Bayes</strong></div><div><span>Training examples</span><strong>${model.training_rows}</strong></div><div><span>Held-out examples</span><strong>${evaluation.test_rows}</strong></div><div><span>Holdout accuracy</span><strong>${percent(evaluation.accuracy)}</strong></div><div><span>Relatable F1 score</span><strong>${decimal(evaluation.f1)}</strong></div></div><p class="note">Author-labeled demo corpus. The small holdout is not a real-world benchmark. Scores are not calibrated probabilities. Neutral includes questions, criticism and non-relatable reactions.</p><details open><summary>Known limitations</summary><p>English only. Negation, sarcasm, mixed-language comments and unfamiliar wording can be misclassified. The fixed holdout includes ${evaluation.mistakes.length} mistakes, preserved in the evaluation file. Human review is required before drawing real campaign conclusions.</p></details><a class="btn" style="margin-top:20px" href="models/evaluation.json" download>${icon('download')} Evaluation results</a></section></div>`}
function experimentView(){const {posts}=current(),e=experiments(posts),av=e.n?e.pairs.reduce((s,p)=>s+p.A.shares/p.A.reach,0)/e.n:null,bv=e.n?e.pairs.reduce((s,p)=>s+p.B.shares/p.B.reach,0)/e.n:null;return `<div class="callout"><div><h2>Does a POV hook get shared more?</h2><p>A compares a text-first opening with B’s acted POV. The unit of analysis is a matched content pair. Organic comparisons are observational; without randomized exposure, differences cannot establish causality.</p></div><span class="badge demo" style="align-self:flex-start">${data.meta.source==='synthetic_demo'?'Simulated experiment':'Observational comparison'}</span></div><div class="metrics">${metric('Matched pairs',number(e.n),'Complete, compatible A/B pairs','experiments')}${metric('A · text-first',percent(av),'Mean pair-level share rate','content')}${metric('B · acted POV',percent(bv),'Mean pair-level share rate','content')}${metric('B − A difference',e.mean===null?'—':(e.mean*100).toFixed(2)+' pp','Percentage points, per pair','strategy')}</div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><h2>What the evidence says</h2><p>Two-sided paired sign-flip permutation test</p></div></div><div class="stats-list"><div><span>p-value</span><strong>${e.p===null?'Insufficient pairs':e.p.toFixed(4)}</strong></div><div><span>95% bootstrap interval</span><strong>${e.interval?e.interval.map(v=>(v*100).toFixed(2)).join(' to ')+' pp':'Need 3+ pairs'}</strong></div><div><span>Descriptive conclusion</span><strong>${e.p===null?'Keep collecting':e.p<.05?'Difference detected':'Inconclusive'}</strong></div></div><p class="note">Exact enumeration up to 16 pairs; 10,000 seeded sign flips beyond that. Interval uses 2,000 seeded pair bootstrap samples; it may differ from the permutation test near the threshold. One preselected outcome: shares ÷ reach. Test assumes exchangeable pair differences under the null. ${data.meta.source==='synthetic_demo'?'Synthetic results cannot validate a real creative strategy.':''}</p></section><section class="panel"><div class="panel-head"><div><h2>Make the next test useful</h2><p>A practical experiment protocol</p></div></div><div class="steps"><div class="step"><div><h3>Change only the first three seconds</h3><p>Hold topic, duration, caption, format and platform fixed.</p></div></div><div class="step"><div><h3>Randomize where possible</h3><p>Use non-overlapping randomized audiences. Organic posts require repeated matched time blocks.</p></div></div><div class="step"><div><h3>Measure after the same window</h3><p>Use 168 hours, preselect share rate, and choose sample size from a minimum useful effect before launch. Do not stop early on a low p-value.</p></div></div></div></section></div><section class="panel tabspacer"><div class="panel-head"><div><h2>Paired observations</h2><p>Missing, duplicate or incompatible variants are excluded. ${posts.filter(p=>p.experiment_id).length-e.n*2} experimental post records excluded.</p></div></div><div class="table-wrap"><table><thead><tr><th>Experiment / topic</th><th>Platform</th><th>A shares / reach</th><th>B shares / reach</th><th>Difference</th></tr></thead><tbody>${e.pairs.map(p=>`<tr><td>${esc(p.id)} · ${esc(p.A.topic)}</td><td>${esc(p.A.platform)}</td><td>${p.A.shares} / ${number(p.A.reach)} · ${percent(p.A.shares/p.A.reach)}</td><td>${p.B.shares} / ${number(p.B.reach)} · ${percent(p.B.shares/p.B.reach)}</td><td>${(p.delta*100).toFixed(2)} pp</td></tr>`).join('')}</tbody></table>${e.n?'':'<div class="empty">Import compatible A/B pairs or reset your filters.</div>'}</div></section>`}
function strategy(){const {posts,comments}=current(),topics=topicStats(posts,comments),top=topics.filter(t=>t.analyzed>0)[0],second=topics.filter(t=>t.analyzed>0)[1],best=[...posts].sort((a,b)=>postMetric(b,'viral')-postMetric(a,'viral'))[0];
 const trends=[...new Set(data.trends.map(t=>t.topic))].filter(t=>state.topic==='All topics'||t===state.topic).map(topic=>({topic,...forecast(data.trends.filter(t=>t.topic===topic&&(!state.start||t.week>=state.start)&&(!state.end||t.week<=state.end)))})).filter(t=>t.rows).sort((a,b)=>b.slope-a.slope);
 return `<div class="callout"><div><h2>${top?`${esc(top.topic)} is the strongest connection signal.`:'Add audience comments to reveal connection signals.'}</h2><p>${top?`${percent(top.relatableRate)} of analyzed comments are classified Relatable across ${top.posts} posts. Use this as a hypothesis for your next campaign, then validate it with real audience feedback.`:'Recommendations update from imported performance and comment records.'}</p></div><button class="btn" id="strategy-export">${icon('download')} Export this analysis</button></div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>A thoughtful plan for next week</h2><p>Recommendations derived from your current selection</p></div></div><div class="recommendation"><div class="strategy-number">01</div><div><h3>${top?`Lead with ${esc(top.topic.toLowerCase())}`:'Collect a representative comment sample'}</h3><p>${top?`Schedule two pieces around this topic. Its ${number(top.relatable)} relatable labels out of ${number(top.analyzed)} analyzed comments are the strongest observed share in this selection.`:'Import comments with stable post IDs before ranking connection.'}</p></div></div><div class="recommendation"><div class="strategy-number">02</div><div><h3>${second?`Keep ${esc(second.topic.toLowerCase())} in the mix`:'Build a second topic comparison'}</h3><p>${second?`Reserve one piece for this theme (${percent(second.relatableRate)} relatability). Keep the format consistent so you can learn whether the topic difference persists.`:'Compare at least two topics under similar publishing conditions.'}</p></div></div><div class="recommendation"><div class="strategy-number">03</div><div><h3>Test the creative, then expand</h3><p>${best?`The highest-scoring post uses ${esc(best.hook.toLowerCase())}, ${best.duration_seconds} seconds and ${esc(best.format.toLowerCase())}. Treat this combination as a candidate for a controlled test, not an established optimum.`:'Collect post performance to identify a candidate format.'} Caption style is not measured independently in this dataset.</p></div></div></section><section class="panel"><div class="panel-head"><div><h2>Connection by topic</h2><p>Model labels · 95% Wilson intervals</p></div></div>${topics.map(t=>{const ci=wilson(t.relatable,t.analyzed);return `<div class="stats-list" style="margin-bottom:12px"><div><span>${esc(t.topic)}<small style="display:block">n = ${t.analyzed}</small></span><strong>${percent(t.relatableRate)}<small style="display:block;font-size:9px;font-weight:400">${ci?ci.map(percent).join(' – '):'No comments'}</small></strong></div></div>`}).join('')}<p class="note">Intervals exclude classifier error, comment clustering and topic selection bias. Rates describe the analyzed sample.</p></section></div>
 <div class="panel-head" style="margin-top:28px"><div><h2>Topics on the horizon</h2><p>Weekly interest index · simple linear extrapolation · ${data.meta.source==='synthetic_demo'?'simulated external trend inputs':'imported external trend inputs'}</p></div></div><p class="report-sub">Date and topic filters apply. Platform filters do not apply to external trends. Four or more weekly observations are required.</p><div class="cards">${trends.map(t=>{const max=100;return `<section class="panel"><span class="topic-tag">${esc(t.topic)}</span><div style="display:flex;align-items:end;justify-content:space-between;margin-top:20px"><strong class="chart-value">${t.next.toFixed(1)}<span class="small muted"> / 100</span></strong><span class="badge ${t.slope<0?'neutral':''}">${t.slope>=0?'+':''}${t.slope.toFixed(1)} / week</span></div><p class="note" style="margin-top:4px">Projection for ${date(t.date)}</p><svg class="trend-spark" viewBox="0 0 250 65" role="img" aria-label="${esc(t.topic)} weekly trend"><path d="${t.rows.map((r,i)=>`${i?'L':'M'}${i/(t.rows.length-1)*240+5} ${62-r.index/max*58}`).join(' ')}" fill="none" stroke="#9db780" stroke-width="2"/>${t.rows.map((r,i)=>`<circle cx="${i/(t.rows.length-1)*240+5}" cy="${62-r.index/max*58}" r="3" fill="#7b9b5e"><title>${r.week}: ${r.index}</title></circle>`).join('')}</svg><p class="note">Last-point backtest error: ${t.error.toFixed(1)} index points. No causal or calibrated predictive claim.</p></section>`}).join('')||'<div class="panel wide empty">No topic has four weekly trend observations in this date range.</div>'}</div>`}
function dataView(){const audit=data.meta.cleaning||{};return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h2>Import a campaign</h2><p>Replace the current dataset with your own exports.</p></div>${icon('data')}</div><p class="small muted">Files are read in your browser. Nothing is uploaded. Data lasts until this page is refreshed; export the JSON bundle to save your work.</p><div class="uploadbox"><h3>One JSON bundle</h3><p class="note" style="margin-top:4px">Use a previously exported dataset or the Python pipeline output.</p><label class="sr-only" for="json-file">Choose a JSON campaign</label><input id="json-file" type="file" accept=".json,application/json"><button class="btn primary" id="import-json" style="margin-top:15px">Import JSON</button></div><details><summary>Or import CSV exports</summary><p>Upload posts and comments together, plus optional weekly trends. Required columns are documented in the schema guide. Blank metrics are rejected, never silently replaced with zero.</p><div class="uploadrow"><label for="posts-file">Posts CSV (required)</label><input id="posts-file" type="file" accept=".csv,text/csv"></div><div class="uploadrow"><label for="comments-file">Comments CSV (required, header-only allowed)</label><input id="comments-file" type="file" accept=".csv,text/csv"></div><div class="uploadrow"><label for="trends-file">Weekly trends CSV (optional)</label><input id="trends-file" type="file" accept=".csv,text/csv"></div><button class="btn primary" id="import-csv">Import CSV files</button></details><div id="import-status" role="status"></div><p class="note">Identical IDs are deduplicated. Conflicting duplicates and orphan comments fail validation. Sentiment is recalculated with the bundled model. Max file size: 15 MB.</p><button class="text-btn" id="restore" style="margin-top:15px">Restore the demo campaign</button></section><section class="panel"><div class="panel-head"><div><h2>Your dataset, at a glance</h2><p>${esc(data.meta.name)} · ${esc(data.meta.source)}</p></div><span class="badge">Validated</span></div><div class="stats-list">${[['Clean post records',data.posts.length],['Analyzed comments',data.comments.length],['Weekly trend records',data.trends.length],['Duplicate posts removed',audit.duplicate_posts??0],['Duplicate comments removed',audit.duplicate_comments??0],['Empty comments removed',audit.empty_comments??0]].map(([l,v])=>`<div><span>${l}</span><strong>${number(v)}</strong></div>`).join('')}</div><div class="insight" style="margin-top:20px">${icon('check')}<span>The demo has no real users. For real campaigns, remove usernames and personal identifiers before import. Keep stable, pseudonymous comment IDs.</span></div><h3 style="margin:23px 0 12px">Export the active campaign</h3><div class="actions" style="flex-wrap:wrap"><button class="btn" data-download="posts">Posts CSV</button><button class="btn" data-download="comments">Comments CSV</button><button class="btn" data-download="trends">Trends CSV</button><button class="btn" id="export-bundle">Full JSON</button></div></section></div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><h2>Project deliverables</h2><p>Supporting files packaged with this dashboard</p></div></div><div class="downloads">${[['reports/strategy-report.pdf','Strategy report','Demo findings, limitations and experiment plan'],['reports/content-series.pdf','The content series','12 concepts, scripts, captions and test hooks'],['reports/methodology.html','Methodology & data dictionary','Metric definitions, import schema and model card'],['reports/deployment.html','Deployment guide','Static hosting and local preview instructions'],['models/sentiment.json','Trained sentiment model','Portable model weights · JSON'],['sentiment.py','NLP classification script','Python 3 · no third-party dependencies']].map(([href,title,desc])=>`<a class="download" href="${href}" ${href.endsWith('.html')?'target="_blank" rel="noopener"':'download'}>${icon('file')}<div><strong>${title}</strong><small>${desc}</small></div><span>↗</span></a>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>From export to insight</h2><p>A reproducible, inspectable workflow</p></div></div><div class="steps"><div class="step"><div><h3>Export at a consistent age</h3><p>Use the same observation window for every post. Match IDs across metrics and comments.</p></div></div><div class="step"><div><h3>Map the documented fields</h3><p>Normalize dates to YYYY-MM-DD, retention to 0–1 and counts to nonnegative integers. Do not invent unavailable platform metrics.</p></div></div><div class="step"><div><h3>Validate, label, analyze</h3><p>Run the Python pipeline or use the CSV importer. Check the audit and review a sample of predicted labels.</p></div></div><div class="step"><div><h3>Export your results</h3><p>Save the full JSON bundle. Export the current strategy analysis from the Strategy tab after an import.</p></div></div></div></section></div>`}
function showDialog(title,html){const d=$('#detail');d.innerHTML=`<div class="dialog-head"><div><div class="eyebrow muted" style="margin-bottom:8px">Relate · Content intelligence</div><h2 style="font-size:22px">${esc(title)}</h2></div><button class="close" aria-label="Close dialog">×</button></div>${html}`;d.querySelector('.close').onclick=()=>d.close();d.showModal();d.onclick=e=>{if(e.target===d&&e.clientX<d.getBoundingClientRect().left)d.close()};bindDialog()}
function bindDialog(){document.querySelectorAll('#detail [data-content]').forEach(b=>b.onclick=()=>{$('#detail').close();showContent(b.dataset.content)});const copy=$('#copy-caption');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(series.find(s=>s.id===copy.dataset.id).caption);toast('Caption copied')}catch{toast('Copy is unavailable. Select the caption text to copy.')}}}
function showContent(id){const s=series.find(s=>s.id===id);if(!s)return;showDialog(s.title,`<div class="dialog-grid"><div><img src="${s.asset}" alt="${esc(s.hook_a)}"><a class="btn" href="${s.asset}" download style="margin-top:14px">${icon('download')} Editable SVG</a><a class="btn" href="content/png/${s.id}.png" download style="margin-top:8px">${icon('download')} Ready-to-post PNG</a></div><div><span class="topic-tag">${esc(s.topic)} · ${s.id}</span>${s.script.map(l=>`<div class="scriptline"><strong>${l.time}</strong><p>${esc(l.voiceover)}</p><small>${esc(l.visual)}</small></div>`).join('')}</div></div><h3 style="margin-top:22px">Two hooks, one story</h3><p class="note">A · ${esc(s.hook_a)}<br>B · ${esc(s.hook_b)}</p><p class="note">${esc(s.experiment)}</p><h3 style="margin-top:22px">Ready-to-use caption</h3><div class="caption">${esc(s.caption)}</div><button class="btn" id="copy-caption" data-id="${s.id}">Copy caption</button>`)}
function showPost(id){const p=data.posts.find(p=>p.post_id===id),comments=data.comments.filter(c=>c.post_id===id),m=metrics([p],comments),asset=series.find(s=>s.id===p.content_id);showDialog(p.title,`<p class="report-sub">${esc(p.platform)} · ${date(p.published_at)} · ${esc(p.topic)} · ${p.observation_hours}-hour observation window</p><div class="metrics two-metrics">${metric('Views',number(p.views),'Repeat plays included','views')}${metric('Weighted viral score',decimal(m.viral),'Descriptive proxy','strategy')}${metric('Relatability',percent(m.relatableRate),`${comments.length} analyzed comments`,'heart')}${metric('Attributed follows',number(p.followers_gained),'Post-level gains','audience')}</div><div class="stats-list">${[['Reach',number(p.reach)],['Likes',number(p.likes)],['Shares',number(p.shares)],['Saves',number(p.saves)],['Reported comments',number(p.comments)],['Retention',percent(p.retention_rate)],['Save-to-share ratio',decimal(m.saveShare)]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>${asset?`<button class="btn primary" style="margin-top:20px" data-content="${asset.id}">View the creative concept ↗</button>`:''}<h3 style="margin:25px 0 10px">A sample of audience comments</h3>${comments.slice(0,3).map(c=>`<div class="comment"><span class="badge ${c.label==='Neutral'?'neutral':''}">${c.label}</span><p>${esc(c.text)}</p></div>`).join('')||'<p class="note">No comments linked to this post.</p>'}`)}
async function fileText(id,required=true){const f=$(id).files[0];if(!f){if(required)throw Error('Choose the required '+id.replace('#','').replace('-file','')+' file first');return null}if(f.size>15*1024*1024)throw Error('File exceeds the 15 MB limit');return f.text()}
function setDataset(bundle){data=bundle;state.start=data.posts[0].published_at;state.end=data.posts.at(-1).published_at;state.platform='All platforms';state.topic='All topics';state.page=1;state.commentPage=1;state.search='';render()}
async function importData(kind){const status=$('#import-status');status.className='note';status.textContent='Validating files and classifying comments…';try{let input;if(kind==='json')input=JSON.parse(await fileText('#json-file'));else{const p=await fileText('#posts-file'),c=await fileText('#comments-file'),t=await fileText('#trends-file',false);input={meta:{source:'user_import',name:'Imported campaign'},posts:parseCSV(p),comments:parseCSV(c,{allowEmpty:true,required:['comment_id','post_id','text','created_at']}),trends:t?parseCSV(t,{allowEmpty:true,required:['topic','week','index']}):[]}}const bundle=validateBundle(input,model);setDataset(bundle);$('#import-status').className='success';$('#import-status').textContent=`Imported ${bundle.posts.length} posts and ${bundle.comments.length} comments. Analysis updated.`;toast('Campaign imported successfully')}catch(e){status.className='error';status.textContent='Import failed: '+e.message}}
function exportStrategy(){const {posts,comments}=current(),t=topicStats(posts,comments),m=metrics(posts,comments),e=experiments(posts);download('relate-strategy-analysis.txt',`RELATE — CURRENT CAMPAIGN ANALYSIS\nSource: ${data.meta.source}\nCampaign: ${data.meta.name}\nFilters: ${state.platform}; ${state.topic}; ${state.start} to ${state.end}\n\n${posts.length} posts; ${number(m.views)} views; ${percent(m.engagement)} engagement; ${number(m.followers_gained)} attributed follows.\n${comments.length} analyzed comments; ${percent(m.relatableRate)} classified Relatable.\n\nTOPIC RANKING\n${t.map(r=>`${r.topic}: ${percent(r.relatableRate)} relatable (n=${r.analyzed}), viral score ${decimal(r.viral)}, ${r.followers_gained} attributed follows`).join('\n')}\n\nA/B COMPARISON\n${e.n} matched pairs. B - A mean share-rate difference: ${e.mean===null?'N/A':(e.mean*100).toFixed(2)+' percentage points'}. p-value: ${e.p??'N/A'}.\n\nACTION\n${t[0]?.analyzed?`Test two new pieces on ${t[0].topic}. Validate the result using human-reviewed comments and consistent observation windows.`:'Collect comments before selecting a topic.'}\n\nLIMITATIONS\n${data.meta.source==='synthetic_demo'?'All campaign results are simulated. ':''}Observational comparisons cannot establish causality. Sampled comments may not represent the full audience. The model uses a small authored English corpus; review its predictions. Viral score is a weighted action proxy, not a predicted probability.\n`)}
